('portablessds', 5, 6, 'Sabrent Rocket XTRM-Q Portable 2TB', 'sabrent-rocket-xtrm-q-portable-2tb', 'SB-XTRM-Q-2TB', 'B0CD2TVQ9B', 'Sabrent Rocket Nano XTRM-Q', 2000, 'External', 'Thunderbolt 3', 2700, 2700, 1200, 3, 'A 2TB portable Thunderbolt 3 SSD from Sabrent in an aluminum body â€” 2700 MB/s sustained read on Thunderbolt hosts. A viable Mac-focused Thunderbolt 3 alternative to the LaCie Rugged SSD Pro 2TB at a similar price tier.', NULL, '["Thunderbolt 3 2700 MB/s","2TB portable aluminum body","Detachable USB-C cable","3-year warranty"]', '["3-year warranty","Premium pricing","Requires Thunderbolt 3/4 host","Heavier than Gen 2 peers"]', 8.6, 0, 1, NULL, NULL);
